module.exports = "<section class=\"bmb_card_button\">\n  @if (isSmall()) {\n    <button\n      type=\"button\"\n      class=\"bmb_card_button-small\"\n      [ngClass]=\"{ 'bmb_card_button-small-flipped': isFlipped }\"\n      (click)=\"handleSmallClick($event)\"\n    >\n      <div class=\"bmb_card_button-small-front\">\n        <bmb-icon\n          [icon]=\"smallIcon()\"\n          [size]=\"24\"\n          class=\"bmb_card_button-small-top-icon\"\n          alt=\"Small icon\"\n        />\n        @if (isABotTemplate(botImage()?.src!)) {\n          <bmb-icon [size]=\"48\" [alt]=\"botImage()?.alt!\" [isSVGTemplate]=\"true\">\n            <ng-template #customIcon>\n              <bmb-bot-icon [iconName]=\"botImage()?.src!\" />\n            </ng-template>\n          </bmb-icon>\n        } @else {\n          <bmb-icon\n            [size]=\"48\"\n            [alt]=\"botImage()?.alt!\"\n            [icon]=\"botImage()?.src!\"\n          ></bmb-icon>\n        }\n        <h3 class=\"bmb_card_button-small-title\">{{ smallTitle() }}</h3>\n      </div>\n      <div class=\"bmb_card_button-small-back\">\n        <bmb-icon\n          icon=\"close\"\n          [size]=\"24\"\n          class=\"bmb_card_button-small-close-icon\"\n        />\n        <div class=\"bmb_card_button-small-text\">\n          {{ smallDescription() }}\n        </div>\n      </div>\n    </button>\n  } @else if (isFullInteractive()) {\n    <section\n      tabindex=\"0\"\n      class=\"bmb_card_button-wrapper\"\n      [ngClass]=\"{\n        'bmb_card_button-wrapper-button':\n          leftContent() &&\n          !leftContentIcon() &&\n          leftContentImage() &&\n          !textLink(),\n        disabled: isDisabled()\n      }\"\n      aria-label=\"button\"\n      (click)=\"handleAddContent($event)\"\n      (keypress)=\"handleAddContent($event)\"\n    >\n      @if (leftContent() || isTemplate() || hasMenu()) {\n        <section class=\"bmb_card_button-box\">\n          @if (leftContent()) {\n            <section\n              class=\"bmb_card_button-left\"\n              [ngClass]=\"{\n                'bmb_card_button-top-header': !leftContentIcon(),\n                'bmb_card_button-top-header-start':\n                  !leftContentIcon() && !!badge()\n              }\"\n            >\n              @if (!!leftContentIcon()) {\n                <div class=\"bmb_card_button-circle\">\n                  <bmb-icon\n                    [icon]=\"leftContentIcon()\"\n                    [size]=\"32\"\n                    class=\"bmb_card_button-circle-icon\"\n                    [alt]=\"componentTitle() || title() || ''\"\n                  />\n                </div>\n              } @else {\n                <img\n                  class=\"bmb_card_button-top-header-image\"\n                  [src]=\"leftContentImage()?.src\"\n                  [alt]=\"leftContentImage()?.alt\"\n                />\n                <section class=\"bmb_card_button-top-header-container\">\n                  @if (!!badge()) {\n                    <bmb-badge\n                      class=\"bmb_card_button-top-header-container-title\"\n                      [text]=\"badge()?.text!\"\n                      [appearance]=\"badge()?.appearance ?? 'normal'\"\n                      [container]=\"badge()?.container ?? true\"\n                    />\n                  }\n                  <h2 class=\"bmb_card_button-top-header-container-title\">\n                    {{ componentTitle() || title() || '' }}\n                  </h2>\n                </section>\n              }\n            </section>\n          }\n          <section class=\"bmb_card_button-leading\">\n            @if (isTemplate()) {\n              <div class=\"bmb_card_button-template\">\n                <ng-content />\n              </div>\n            }\n\n            @if (hasMenu()) {\n              <bmb-dropdown-menu\n                class=\"bmb_card_button-menu\"\n                [items]=\"menuItems()\"\n              />\n            }\n          </section>\n        </section>\n      }\n      @if (!!leftContentIcon() && !leftContentImage()) {\n        <section\n          tabindex=\"0\"\n          class=\"bmb_card_button-header\"\n          (click)=\"handleTitleClick($event)\"\n          aria-label=\"button\"\n          (keypress)=\"handleTitleClick($event)\"\n        >\n          <h2 class=\"bmb_card_button-header-text\">\n            {{ componentTitle() || title() || '' }}\n          </h2>\n          <bmb-icon\n            [icon]=\"icon()\"\n            [size]=\"16\"\n            class=\"bmb_card_button-header-icon\"\n          />\n        </section>\n      }\n\n      @if (\n        (leftContent() &&\n          !leftContentIcon() &&\n          leftContentImage() &&\n          textLink()) ||\n        body()\n      ) {\n        <section class=\"bmb_card_button-body\">\n          {{ body() }}\n\n          @if (\n            leftContent() &&\n            !leftContentIcon() &&\n            leftContentImage() &&\n            textLink()\n          ) {\n            <bmb-text-link\n              [textLink]=\"textLink()?.label!\"\n              icon=\"\"\n              [link]=\"textLink()?.link!\"\n              [target]=\"textLink()?.target!\"\n            />\n          }\n        </section>\n      }\n      <div class=\"bmb_card_button-custom-content\">\n        <ng-container [ngTemplateOutlet]=\"customContent() ?? null\" />\n      </div>\n    </section>\n  } @else {\n    <button\n      type=\"button\"\n      class=\"bmb_card_button-add\"\n      [disabled]=\"isDisabled()\"\n      (click)=\"handleAddContent($event)\"\n    >\n      <bmb-icon\n        [icon]=\"icon()\"\n        [size]=\"48\"\n        class=\"bmb_card_button-add-icon\"\n        [isFill]=\"false\"\n        [alt]=\"componentTitle() || title() || ''\"\n      />\n      <div class=\"bmb_card_button-add-title\">\n        {{ componentTitle() || title() || '' }}\n      </div>\n    </button>\n  }\n</section>\n";

